-- Reference metadata for the 45 PPDT pictures (reviewed = false until checked).
on conflict (id) do update set scene=excluded.scene, characters=excluded.characters, mood=excluded.mood, setting=excluded.setting, key_elements=excluded.key_elements, plausible_themes=excluded.plausible_themes, positive_resolutions=excluded.positive_resolutions, olq_cues=excluded.olq_cues, updated_at=now();
